head.script:
scwin.screenId = "jldstf07221";

///////// 1. 변수 및 선언 영역 /////////

scwin.contnId = undefined;

scwin.gRegEmpNo = undefined;

scwin.bbsTypeCd = "4";

scwin.vScrenID = "ULDSTF07221.gfm";


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.fil.showObj(ipt_tboxMktTp, false);
        const parentYn = $c.frame.Provider("../").contnId;
        if (parentYn == null || parentYn === "undefined" || parentYn.length == 0) {
            scwin.contnId = "input";
        } else {
            getContnId = $c.frame.Provider("../").fn_getContnId;
            scwin.contnId = getContnId();
        }
        if (scwin.contnId !== "input") {
            scwin.fn_read();
        } else {
            scwin.setFileDataHeader();
            scwin.fn_SetSaveHeader();
            $c.util.getComponent("ipt_tboxWrtrEmpNm").setValue($c.session.getUserInfo("empNm"));
            $c.util.getComponent("ipt_tboxWrtDdtm").setValue($c.date.formatDate("yyyy-mm-dd hh:mm:ss"));
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07221.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { console.warn("[sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0"); };

scwin.dts_ContentsDel = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ContentsDel')) : $c.util.getComponent('dts_ContentsDel');

scwin.dts_ContentsInfo = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dts_ContentsInfo')) : $c.util.getComponent('dts_ContentsInfo');

scwin.dts_fileList = typeof __krxRowShim === 'function' ? __krxRowShim($c.util.getComponent('dtsFileList')) : $c.util.getComponent('dtsFileList');

scwin.upd_infFind = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_infFind') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_infFind"]');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07221.onpageload' });
    }
};


