    try {
        /* sdd-asis-lifecycle:begin grd_fileList_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if (scwin.dts_fileList.getRowStatus(scwin.dts_fileList.getRowPosition()) == 0) {
            await scwin.filedown(scwin.dts_fileList.getCellData(row, "ATTACH_SEQ"));
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf07221.grd_fileList_onclick' }); }
};

