/**
 * @method
 * @name scwin.checkMaxLength1
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj size lbl
 * @returns
 * @hidden N
*/
scwin.checkMaxLength1 = async function (obj, size, lbl) {
    /* sdd-asis-lifecycle:begin checkMaxLength1 — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const overLen = ($c.str.getByteLength(obj.value) - size);
    if (overLen > 0) {
        await $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};


